package com.fintaxpro;
import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class FinanceTest{
 @Test void reservesNeverAddFunds(){Finance.State s=Finance.apply(Finance.empty("Test"),"account",Map.of("name","Bank","opening",10000000,"asOf",Finance.today().toString()));String a=s.accounts().get(0).id();s=Finance.apply(s,"pot",Map.of("name","Buffer","accountId",a,"target",10000000));s=Finance.apply(s,"allocate",Map.of("id",s.pots().get(0).id(),"amount",2000000));assertEquals(10000000,Finance.balance(s));assertEquals(2000000,Finance.reserved(s));Finance.State saved=s;assertThrows(IllegalArgumentException.class,()->Finance.apply(saved,"allocate",Map.of("id",saved.pots().get(0).id(),"amount",9000000)));}
 @Test void verifiedTaxBoundaries(){assertEquals(0L,Finance.tax(120000000,0,"NEW").get("total"));assertEquals(104000L,Finance.tax(120100000,0,"NEW").get("total"));assertEquals(10920000L,Finance.tax(150000000,0,"NEW").get("total"));assertThrows(IllegalArgumentException.class,()->Finance.tax(500000001,0,"NEW"));}
 @Test void settlementCountsExpectedIncomeOnce(){Finance.State s=Finance.apply(Finance.empty("Test"),"account",Map.of("name","Bank","opening",10000000,"asOf",Finance.today().toString()));s=Finance.apply(s,"commitment",Map.of("accountId",s.accounts().get(0).id(),"description","Client","amount",500000,"direction","INCOME","scope","BUSINESS","category","Client payment","date",Finance.today().plusDays(2).toString(),"frequency","NONE","priority","OBLIGATION"));assertEquals(10000000,Finance.balance(s));var event=Finance.events(s,Finance.today().plusDays(7)).get(0);s=Finance.apply(s,"settle",Map.of("id",event.schedule().id(),"occurrence",event.occurrence()));assertEquals(10500000,Finance.balance(s));assertTrue(Finance.events(s,Finance.today().plusDays(7)).isEmpty());Finance.State saved=s;assertThrows(IllegalArgumentException.class,()->Finance.apply(saved,"settle",Map.of("id",event.schedule().id(),"occurrence",event.occurrence())));}
}
